gu1(){return"\u0ca8\u0cae\u0ccd\u0cae \u0ca4\u0c82\u0ca1 \u0caa\u0ccd\u0cb0\u0ca4\u0cbf \u0c97\u0ccd\u0cb0\u0cbe\u0cb9\u0c95\u0cb0\u0cbf\u0c97\u0cc6 \u0c95\u0cb0\u0cc6 \u0cae\u0cbe\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6. \u0cb8\u0c82\u0c96\u0ccd\u0caf\u0cc6 \u0ca4\u0caa\u0ccd\u0caa\u0cbe\u0c97\u0cbf\u0ca6\u0ccd\u0ca6\u0cb0\u0cc6, \u0c86\u0cb8\u0c95\u0ccd\u0ca4\u0cbf \u0c87\u0cb2\u0ccd\u0cb2\u0ca6\u0cbf\u0ca6\u0ccd\u0ca6\u0cb0\u0cc6 \u0c85\u0ca5\u0cb5\u0cbe \u0c88\u0c97\u0cbe\u0c97\u0cb2\u0cc7 \u0ca6\u0cbe\u0c96\u0cb2\u0cbe\u0c97\u0cbf\u0ca6\u0ccd\u0ca6\u0cb0\u0cc6 \u0cb6\u0cbf\u0cab\u0cbe\u0cb0\u0cb8\u0cc1 \u0cae\u0cc1\u0c9a\u0ccd\u0c9a\u0cb2\u0cbe\u0c97\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6. \u0c95\u0cbe\u0cb0\u0ca3 \u0cb6\u0cbf\u0cab\u0cbe\u0cb0\u0cb8\u0cbf\u0ca8\u0cb2\u0ccd\u0cb2\u0cbf \u0c95\u0cbe\u0ca3\u0cbf\u0cb8\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6."},
gu2(){return"\u0ca8\u0ca8\u0ccd\u0ca8 \u0cb6\u0cbf\u0cab\u0cbe\u0cb0\u0cb8\u0cc1 \u0c8f\u0c95\u0cc6 \u0caa\u0cb0\u0cbf\u0cb6\u0cc0\u0cb2\u0ca8\u0cc6 \u0c86\u0c97\u0cb2\u0cbf\u0cb2\u0ccd\u0cb2?"},
gu3(){return"\u0cb9\u0ccc\u0ca6\u0cc1, \u0cac\u0cc7\u0cb0\u0cc6 \u0c85\u0c97\u0ca4\u0ccd\u0caf\u0c95\u0ccd\u0c95\u0cc6. \u0c85\u0ca6\u0cc7 \u0c85\u0c97\u0ca4\u0ccd\u0caf\u0c95\u0ccd\u0c95\u0cc6 \u0cae\u0cca\u0ca6\u0cb2 \u0cb6\u0cbf\u0cab\u0cbe\u0cb0\u0cb8\u0cc1 \u0cb8\u0cc1\u0cb0\u0c95\u0ccd\u0cb7\u0cbf\u0ca4, \u0c8e\u0cb0\u0ca1\u0ca8\u0cc6\u0caf\u0ca6\u0cc1 \u0cb2\u0cc6\u0c95\u0ccd\u0c95\u0c95\u0ccd\u0c95\u0cc6 \u0cac\u0cb0\u0ca6\u0cbf\u0cb0\u0cac\u0cb9\u0cc1\u0ca6\u0cc1."},
